import{_ as t,o as s,c as i,a9 as a}from"./chunks/framework.asyjyako.js";const u=JSON.parse('{"title":"Send PerfChecker evidence to an MCP assistant","description":"","frontmatter":{},"headers":[],"relativePath":"mcp-advisor.md","filePath":"mcp-advisor.md","lastUpdated":null}'),o={name:"mcp-advisor.md"};function n(r,e,d,l,p,c){return s(),i("div",null,[...e[0]||(e[0]=[a(`<h1 id="Send-PerfChecker-evidence-to-an-MCP-assistant" tabindex="-1">Send PerfChecker evidence to an MCP assistant <a class="header-anchor" href="#Send-PerfChecker-evidence-to-an-MCP-assistant" aria-label="Permalink to &quot;Send PerfChecker evidence to an MCP assistant {#Send-PerfChecker-evidence-to-an-MCP-assistant}&quot;">​</a></h1><p>This optional provider is for users who already have an MCP server offering an advice tool and a saved PerfChecker diagnosis. If you only want to run or inspect tests, you do not need this page. Start with <a href="./advisor-ui">advisor setup</a> to select a provider before configuring protocol details.</p><p>This integration sends a customizable request and bounded PerfChecker evidence to one explicitly configured MCP advice tool. The default request asks, in English, for performance-improvement clues, distinguishes observations from hypotheses, and asks how to verify a proposed correction. It does not require local model weights.</p><p>MCP is a tool protocol, not a model endpoint. Your server must expose a tool that can answer a request, directly or through its own assistant. A server containing only unrelated data tools cannot generate performance advice by itself. PerfChecker does not install or start that server.</p><h2 id="Configure-the-assistant" tabindex="-1">Configure the assistant <a class="header-anchor" href="#Configure-the-assistant" aria-label="Permalink to &quot;Configure the assistant {#Configure-the-assistant}&quot;">​</a></h2><p>Install HTTP in the dedicated PerfChecker controller environment. Copy <code>examples/advisor-corpus/mcp-local.json</code> from the repository to your project&#39;s <code>perf/advisor.json</code>. Replace its example address and tool name with your server&#39;s actual settings; <code>ask</code> is a placeholder, not a guaranteed standard MCP tool.</p><table tabindex="0"><thead><tr><th style="text-align:right;">Setting</th><th style="text-align:right;">Purpose</th></tr></thead><tbody><tr><td style="text-align:right;"><code>protocol</code></td><td style="text-align:right;"><code>mcp_http</code> for the MCP endpoint</td></tr><tr><td style="text-align:right;"><code>endpoint</code></td><td style="text-align:right;">Local HTTP or explicitly allowed remote HTTPS MCP endpoint</td></tr><tr><td style="text-align:right;"><code>mcp_version</code></td><td style="text-align:right;"><code>2026-07-28</code>, or <code>2025-11-25</code> for a legacy server</td></tr><tr><td style="text-align:right;"><code>mcp_tool</code></td><td style="text-align:right;">The one selected advice tool; its existence is checked with <code>tools/list</code></td></tr><tr><td style="text-align:right;"><code>mcp_prompt_argument</code></td><td style="text-align:right;">String argument receiving the combined prompt and evidence, usually <code>prompt</code> or <code>question</code></td></tr><tr><td style="text-align:right;"><code>mcp_arguments</code></td><td style="text-align:right;">Additional arguments required by that tool; cannot replace the generated prompt argument</td></tr><tr><td style="text-align:right;"><code>instructions</code></td><td style="text-align:right;">Your preferences, up to 5,000 characters; empty uses the default request</td></tr><tr><td style="text-align:right;"><code>mcp_response</code></td><td style="text-align:right;"><code>text</code> for advice only; <code>structured</code> for validated references and experiment selection</td></tr><tr><td style="text-align:right;"><code>timeout</code></td><td style="text-align:right;">Total isolated worker time limit, including startup and MCP exchanges</td></tr></tbody></table><p>The <code>model</code> value is a report label for MCP. Selecting a model behind the tool, if supported by that server, uses its documented <code>mcp_arguments</code> instead.</p><p>In VS Code, open <strong>Model settings</strong> to use the <a href="./advisor-ui">guided advisor panel</a>, test the connection and select a discovered tool. You can also set <code>perfchecker.advisorConfig</code> to <code>perf/advisor.json</code>, or use the corresponding settings: <code>advisorProtocol</code>, <code>advisorEndpoint</code>, <code>advisorMcpTool</code>, <code>advisorMcpPromptArgument</code>, <code>advisorMcpArguments</code>, <code>advisorMcpVersion</code>, <code>advisorMcpResponse</code> and <code>advisorInstructions</code>. The configuration file takes precedence over individual settings. Run a diagnosis and choose <strong>Explain with configured model</strong>.</p><p>For a remote server, set <code>allow_remote=true</code> and use HTTPS. Name the optional Bearer-token environment variable in <code>api_key_env</code>; do not store the token in the configuration. OAuth login/refresh is not implemented. A compatible Chat Completions model uses <code>chat_completions</code>, not <code>mcp_http</code>.</p><h2 id="Prompt-and-results" tabindex="-1">Prompt and results <a class="header-anchor" href="#Prompt-and-results" aria-label="Permalink to &quot;Prompt and results {#Prompt-and-results}&quot;">​</a></h2><p>The default text-mode request asks for concrete clues to improve common Julia code, supporting observations, hypotheses, candidate changes and verification. Your <code>instructions</code> are prepended to this request. The payload contains bounded recommendation IDs, rules, observations, proposed experiments, verifications and limits. Raw logs, source files, credentials and workspace roots are not added. This is a summary of saved evidence, not the full bundle or source code.</p><p>Text replies, limited to 16,000 characters, appear separately from deterministic findings in VS Code, JSON/Markdown reports and the shared HTML/REPL/Pluto view. They carry <code>reference_status=&quot;unstructured_not_verified&quot;</code>; individual statements are not assigned invented citations. Embedded HTML is displayed as text. No instruction or suggested command in that reply is executed.</p><p>Julia and the CLI use the same file:</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">using</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> PerfChecker</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">config </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> load_advisor_config</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;perf/advisor.json&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">result </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> narrate_advice</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">read_advice</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;perf/results/advice.json&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">); config)</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">display</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">investigation_view</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(result))</span></span></code></pre></div><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">julia</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --startup-file=no</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --project=.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -e</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;using PerfChecker; exit(perfchecker_main(ARGS))&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> narrate</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --source=perf/results/advice.json</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --advisor-config=perf/advisor.json</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --project=perf</span></span></code></pre></div><h2 id="Optional-bounded-investigation" tabindex="-1">Optional bounded investigation <a class="header-anchor" href="#Optional-bounded-investigation" aria-label="Permalink to &quot;Optional bounded investigation {#Optional-bounded-investigation}&quot;">​</a></h2><p>Keep <code>advisorInvestigates=false</code> for advice only. To let the assistant select experiments, explicitly choose <code>mcp_response=&quot;structured&quot;</code> and enable <code>advisorInvestigates</code>. The selected tool must follow the JSON response contract:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;cards&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;evidence_id&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;an ID supplied in the request&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;explanation&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Supported advice&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}],</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;experiment_id&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;stop&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>It may replace <code>stop</code> with one of the experiment IDs supplied in that request. Unknown/duplicate evidence IDs and unknown experiment IDs are rejected. The existing count and duration budgets apply; PerfChecker executes only declared experiments. Text mode refuses experiment selection. There is no unrestricted handover, source editing, automatic baseline adoption or publication.</p><p>The configured server/tool has its own permissions. This integration supplies neither filesystem roots nor access to the target repository; select an advice tool whose behavior matches this mode of use.</p><h2 id="Compatibility-and-failure-handling" tabindex="-1">Compatibility and failure handling <a class="header-anchor" href="#Compatibility-and-failure-handling" aria-label="Permalink to &quot;Compatibility and failure handling {#Compatibility-and-failure-handling}&quot;">​</a></h2><p>The client supports the HTTP subset needed for one selected advice tool: JSON and request-scoped SSE responses, paginated tool discovery (32 pages max), legacy initialization/session release, and modern request metadata and annotated argument headers. Protocol revisions are explicit; there is no silent downgrade. Responses are capped at 1 MB, redirects and automatic retries are disabled.</p><p>Stdio, deprecated HTTP+SSE endpoints, sampling, elicitation, roots, subscriptions and arbitrary tool chains are not implemented. Unsupported client interactions, missing tools, errors and malformed structured replies preserve the deterministic fallback. Cancellation stops the local worker; remote interruption depends on the server honoring transport cancellation. No external server is qualified merely by passing the local protocol tests.</p><p>Protocol references: <a href="https://modelcontextprotocol.io/specification/2026-07-28/basic/versioning" target="_blank" rel="noreferrer">versioning</a>, <a href="https://modelcontextprotocol.io/specification/2026-07-28/basic/transports/streamable-http" target="_blank" rel="noreferrer">Streamable HTTP</a>.</p>`,25)])])}const g=t(o,[["render",n]]);export{u as __pageData,g as default};
